.payment_method_yekpay .payment_box p {
    display: none !important;

/* Disable the Gravatar link on the WooCommerce My Account navigation (Kadence Fix) */
#post-8 > div > div > div.woocommerce > div.account-navigation-wrap > div > div.kadence-customer-image > a {
    pointer-events: none !important;
    cursor: default !important;
}
